SELECT f1.subject_id, f1.hadm_id, f1.stay_id, f1.first_careunit, f1.last_careunit, f1.intime, f1.outtime, f1.los, f1.gender, f1.anchor_age, f1.anchor_year, f1.anchor_year_group, f1.icd_code, f1.icd_version, f1.itemid, f1.value, f1.valueuom, f1.seq_num, f1.poe_id, f1.poe_seq, f1.orderid, f1.linkorderid, f1.ordercategoryname, f1.ordercategorydescription, f1.pharmacy_id, f1.drug, f1.dose_val_rx, f1.dose_unit_rx, f1.rate, f1.rateuom, f1.statusdescription, lag(f1.drug) OVER (PARTITION BY f1.subject_id, f1.hadm_id ORDER BY f1.itemid) AS previous_drug, lead(f1.drug) OVER (PARTITION BY f1.subject_id, f1.hadm_id ORDER BY f1.itemid) AS next_drug, COUNT(CASE WHEN f1.value = 'Y' THEN 1 END)::FLOAT / NULLIF(COUNT(f1.value), 0) AS proportion_yes FROM f1 WHERE f1.icd_code IN ('42888', '42848', '42849') AND f1.icd_version = 'V4' AND f1.gender = 'F' AND f1.anchor_age BETWEEN 37 AND 47 AND f1.stay_id >= 144 GROUP BY f1.subject_id, f1.hadm_id, f1.stay_id, f1.first_careunit, f1.last_careunit, f1.intime, f1.outtime, f1.los, f1.gender, f1.anchor_age, f1.anchor_year, f1.anchor_year_group, f1.icd_code, f1.icd_version, f1.itemid, f1.value, f1.valueuom, f1.seq_num, f1.poe_id, f1.poe_seq, f1.orderid, f1.linkorderid, f1.ordercategoryname, f1.ordercategorydescription, f1.pharmacy_id, f1.drug, f1.dose_val_rx, f1.dose_unit_rx, f1.rate, f1.rateuom, f1.statusdescription;